#define MAX_N 100000

int n;
int a[2 * MAX_N];

bool check(int x) {
    // We'll work with array of -1 (less than x) and 1 (>= x)
    // We need to find the top value in median pyramid.
    // We find the closest pair of same signs near the center.
    int len = 2 * n - 1;
    int mid = n - 1; // zero-indexed center index
    for (int d = 0; d < n; d++) {
        int left = mid - d;
        int right = mid + d;
        if (left >= 0 && (a[left] >= x) == (a[left + 1] >= x)) {
            return a[left] >= x;
        }
        if (right < len && (a[right] >= x) == (a[right - 1] >= x)) {
            return a[right] >= x;
        }
    }
    // Fallback: if no adjacent equal found (shouldn't happen for odd length > 1)
    return a[mid] >= x;
}

