int main() {
    int N;
    scanf("%d", &N);

    // step N has 2N-1 blocks
    int size = 2*N - 1;
    int *current = malloc(size * sizeof(int));

    for (int i = 0; i < size; i++) {
        scanf("%d", &current[i]);
    }

    // Go from step N up to step 1
    for (int step = N; step > 1; step--) {
        // current step has 2*step-1 blocks
        // next step (above) has 2*(step-1)-1 = 2*step-3 blocks
        int new_size = 2*(step-1) - 1;
        int *next = malloc(new_size * sizeof(int));
        for (int j = 0; j < new_size; j++) {
            // block j of upper step uses blocks j, j+1, j+2 of current step
            next[j] = median3(current[j], current[j+1], current[j+2]);
        }
        free(current);
        current = next;
    }

    printf("%d\n", current[0]);
    free(current);
    return 0;
}

