        vector<int> cur(M);
        for (int i = 0; i < M; i++) {
            cur[i] = (perm[i] >= x);
        }
        // Step by step reduction
        int len = M;
        while (len > 1) {
            vector<int> nxt(len - 2);
            for (int i = 0; i < len - 2; i++) {
                // Median of three consecutive values
                int sum = cur[i] + cur[i+1] + cur[i+2];
                nxt[i] = (sum >= 2);
            }
            cur = move(nxt);
            len -= 2;
        }
        return cur[0] == 1;
    };

