#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> a(2 * N - 1);
    for (int i = 0; i < 2 * N - 1; i++) cin >> a[i];

    // For any threshold x, define b[i] = (a[i] >= x).
    // The value at the top is >= x iff, in this binary pyramid,
    // the top becomes 1 under majority-of-three transitions.
    //
    // It can be shown that this depends only on the earliest adjacent equal pair
    // in the bottom row:
    // - if the earliest adjacent equal pair is 1, top is 1
    // - if it is 0, top is 0
    // - if no adjacent equal pair exists, the row alternates and top equals
    //   the middle element after N-1 reductions, i.e. depends on parity:
    //   specifically b[N-1].
    //
    // Then we binary search the maximum x such that top >= x.

    auto top_ge = [&](int x) -> bool {
        vector<int> b(2 * N - 1);
        for (int i = 0; i < 2 * N - 1; i++) b[i] = (a[i] >= x ? 1 : 0);

        int bestDist = INT_MAX;
        int val = -1;

        for (int i = 0; i + 1 < 2 * N - 1; i++) {
            if (b[i] == b[i + 1]) {
                int dist = min(i + 1, (2 * N - 2) - i); 
                // equivalent to step level where this pair first determines the top
                if (dist < bestDist) {
                    bestDist = dist;
                    val = b[i];
                }
            }
        }

        if (bestDist == INT_MAX) {
            return b[N - 1];
        } else {
            return val == 1;
        }
    };

    int lo = 1, hi = 2 * N - 1, ans = 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (top_ge(mid)) {
            ans = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }

    cout << ans << '\n';
    return 0;
}

