public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = 2 * N - 1;
        int[] a = new int[M];
        for (int i = 0; i < M; i++) {
            a[i] = sc.nextInt();
        }
        int lo = 1, hi = M;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (check(a, N, mid)) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        System.out.println(lo);
    }

    static boolean check(int[] a, int N, int x) {
        int len = 2 * N - 1;
        int[] b = new int[len];
        for (int i = 0; i < len; i++) {
            b[i] = (a[i] >= x) ? 1 : 0;
        }
        // We only need center part until we reach top
        int left = 0, right = len - 1;
        while (left < right) {
            int mid = (left + right) / 2;
            // Check the three central values
            int leftVal = b[mid - 1];
            int centerVal = b[mid];
            int rightVal = b[mid + 1];
            // The median of three bits = majority
            int newCenter;
            if (leftVal + centerVal + rightVal >= 2) {
                newCenter = 1;
            } else {
                newCenter = 0;
            }
            // If the new center matches something on sides, propagate
            // We'll just build next level
            int[] next = new int[right - left - 1];
            for (int i = 0; i < next.length; i++) {
                int sum = b[left + i] + b[left + i + 1] + b[left + i + 2];
                next[i] = (sum >= 2) ? 1 : 0;
            }
            b = next;
            left = 0;
            right = b.length - 1;
        }
        return b[0] == 1;
    }
}

