        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int size = 2 * N - 1;
        int[] current = new int[size];
        for (int i = 0; i < size; i++) {
            current[i] = sc.nextInt();
        }

        // Compute upward from step N to step 1
        for (int step = N - 1; step >= 1; step--) {
            int newSize = 2 * step - 1;
            int[] next = new int[newSize];
            for (int j = 0; j < newSize; j++) {
                int a = current[j];
                int b = current[j + 1];
                int c = current[j + 2];
                // median of a, b, c
                next[j] = median(a, b, c);
            }
            current = next;
        }

        System.out.println(current[0]);
    }

    static int median(int a, int b, int c) {
        if (a > b) { int t = a; a = b; b = t; }
        if (b > c) { int t = b; b = c; c = t; }
        if (a > b) { int t = a; a = b; b = t; }
        return b;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = 2 * N - 1;
        int[] a = new int[M];
        for (int i = 0; i < M; i++) a[i] = fs.nextInt();

        // Binary search the answer x:
        // Let good(v) = whether the top value is >= v.
        // For a fixed v, bottom row becomes binary:
        // b[i] = 1 if a[i] >= v else 0.
        // Each upper cell is the majority of three below cells.
        // We need to know whether the final top bit is 1.
        int lo = 1, hi = 2 * N - 1;
        while (lo < hi) {
            int mid = (lo + hi + 1) >>> 1;
            if (topAtLeast(a, N, mid)) lo = mid;
            else hi = mid - 1;
        }
        System.out.println(lo);
    }

    // Returns whether the top value is >= x.
    static boolean topAtLeast(int[] a, int N, int x) {
        int M = a.length;
        int[] b = new int[M];
        for (int i = 0; i < M; i++) b[i] = (a[i] >= x ? 1 : 0);

        // Key observation:
        // For binary values, the top is determined by the first level from the bottom
        // where there exists an adjacent equal pair. If the nearest such pair to the center
        // occurs at distance d from the center, then that pair's value determines the top.
        //
        // Concretely, among pairs (i, i+1), if b[i] == b[i+1], then this equality propagates upward
        // and can determine the top once its "cone" reaches the center. The earliest such event
        // is the pair minimizing max(|i-(N-1)|, |(i+1)-(N-1)|), which is equivalent to minimizing
        // distance of the pair to the center.
        //
        // We can scan outward from the center.
        int center = N - 1;

        // Check pair (center-1, center) and (center, center+1), then expand.
        for (int d = 0; d <= N - 2; d++) {
            int leftStart = center - 1 - d;
            if (leftStart >= 0 && b[leftStart] == b[leftStart + 1]) {
                return b[leftStart] == 1;
            }
            int rightStart = center + d;
            if (rightStart + 1 < M && b[rightStart] == b[rightStart + 1]) {
                return b[rightStart] == 1;
            }
        }

        // If no adjacent equal pair exists, the row must alternate 0101... or 1010...
        // Then the top equals the center bit.
        return b[center] == 1;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
